pdf.body:










BIÊN BẢN NGHIỆM THU








                    Số:
                    ${record.name?html}




        <#assign add = record.custrecord_scv_accept_sub.custrecord_scv_o2c_if_add?replace("
", ", ")>

Hôm nay,
            ngày ${record.custrecord_scv_accept_do_date?string["dd"]}
            tháng ${record.custrecord_scv_accept_do_date?string["MM"]}
            năm ${record.custrecord_scv_accept_do_date?string["YYYY"]}
            ${(record.custrecord_scv_accept_place?has_content)?then(', tại ${record.custrecord_scv_accept_place?html}', ' '
            )}
            ${(record.custrecord_scv_accept_sub?has_content)?then(', ${record.custrecord_scv_accept_sub?html}', ' ' )}
            ${(record.custrecord_scv_accept_sub?has_content)?then(', ${add?html}', ' ' )}




            Thành phần tham gia nghiệm thu gồm có:



            <#if record.custrecord_scv_accept_requester?has_content>


                1. Ông/ Bà: ${record.custrecord_scv_accept_requester.custentity_scv_legal_name?html}
                Chức vụ: ${record.custrecord_scv_accept_requester.title?html}

        </#if>
            <#if record.custrecord_scv_accept_manager?has_content>


                2. Ông/ Bà: ${record.custrecord_scv_accept_manager.custentity_scv_legal_name?html}
                Chức vụ: ${record.custrecord_scv_accept_manager.title?html}

        </#if>

            <#if record.custrecord_scv_accept_emp2?has_content>


                3. Ông/ Bà: ${record.custrecord_scv_accept_emp2.custentity_scv_legal_name?html}
                Chức vụ: ${record.custrecord_scv_accept_emp2.title?html}

    </#if>

            <#if record.custrecord_scv_accept_emp3?has_content>


                4. Ông ${record.custrecord_scv_accept_emp3.custentity_scv_legal_name?html}
                Chức vụ: ${record.custrecord_scv_accept_emp3.title?html}

            </#if>




            Nội dung nghiệm thu:














                    Tên vật tư/ Quy cách


Tiêu chuẩn nghiệm thu



Thực tế nghiệm thu




                    Kết quả
                    Có tải
                    K. tải




              <#if items.arrItem?has_content>
                <#list items.arrItem as item>
                <#assign rowSpanVal = item.rowspan?number?default(1)>


                    <#if rowSpanVal gt 0>
                    ${item.ten_vat_tu?html?replace("\n", "
")}
                    <#else>

                    </#if>
                    ${item.tc_nghiem_thu?html?replace("\n", "
")}
                    ${item.kq?html?replace("\n", "
")}
                    ${item.cotai?html}
                    ${item.khongtai?html}

                </#list>
                </#if>





* Kết luận: 

${record.custrecord_scv_accept_conclusions?html}

.......................................................................................................................................................................
.......................................................................................................................................................................
.......................................................................................................................................................................







        Nơi gửi

        - P.VT

        - P.KT

        - Lưu P.KyT



        THÀNH VIÊN NGHIỆM THU

        ${record.custrecord_scv_accept_requester.custentity_scv_legal_name?html}   ${record.created?date?string["dd/MM/yyyy HH:mm:ss"]}

        ${record.custrecord_scv_accept_manager.custentity_scv_legal_name?html}   ${record.custrecord_scv_accept_date_time_1?date?string["dd/MM/yyyy HH:mm:ss"]}

        ${record.custrecord_scv_accept_emp2.custentity_scv_legal_name?html}   ${record.custrecord_scv_accept_date_time_2?date?string["dd/MM/yyyy HH:mm:ss"]}

        ${record.custrecord_scv_accept_emp3.custentity_scv_legal_name?html}   ${record.custrecord_scv_accept_date_time_3?date?string["dd/MM/yyyy HH:mm:ss"]}




PHÊ DUYỆT

        ${record.custrecord_scv_accept_approver.custentity_scv_legal_name?html} ${record.custrecord_nvd_accept_date_time_fn?date?string["dd/MM/yyyy HH:mm:ss"]}
